ken_mtime_cached federation_pull_uses_batch_upsert hub_pull_kick_flag_wiring publish_verify_scans_binary_text snippets_watch_inner_window_headroom dev_only_targets_need_exists_guard slot_claim_requires_cwd_match wake_injection_length_capped dead_anchor_falls_back_to_cwd_reanchor magpie_hook_readonly_queue magpie_hosting_requires_heartbeat pi_respawn_targets_own_cwd hub_wakeless_envelope_composes_wake delivery_error_loop_bounces_after_strikes win_local_host_sans_uname dsh_inbox_win_cwd_matches dsh_host_scripts_purge_cookie_on_token win_dsh_mount_uses_wsl_bridge stdio_startup_registration_arms_heartbeat dsh_win_host_breaks_interop_pipes polling_mode_scan_always_full win_dsh_purewin_insert_contract win_dsh_host_ps1_native_contract win_dsh_host_magpie_key_env_first public_readme_no_stale_delivery_terms dev_only_lint_gated_by_publish_sh publish_tree_matches_head pi_inbox_rcpt_claim_before_inject pi_inbox_primary_session_exclusive fed_pull_single_round_trip pi_subagent_mailbox_tools_denied mcp_hub_spawn_detached mcp_http_identity_header untrusted_ids_never_reach_paths registry_transient_unread_defers_sweep hub_busy_probe_never_blocks; do
  echo "== ${rule}"
  python3 "lints/${rule}.py" || status=1
done
if command -v node >/dev/null 2>&1; then
  echo "== gateway-mailbox hooks (node --test)"
  if ! (cd plugins/gateway-mailbox && node --test test.mjs 2>&1 | tail -20); then
    status=1
  fi
else
  echo "== gateway-mailbox hooks (node --test): skipped, node not installed"
fi
exit "${status}"
